class VideoStreamsResult {
  final List<AudioStream> audioStreams;
  final List<VideoStream> videoStreams;
  final List<VideoStream> mixedStreams;
  final VideoStreamInfo? info;
  final VideoPlayabilty playability;
  final LoudnessDBData? loudnessDBData;
  final String? hlsManifestUrl;
  final String? dashManifestUrl;
  final bool expired;
  final String? videoId;
  final List<Caption> captions;
  final VideoOverlayData? overlay;
  final List<EndscreenItemBase> endscreens;

  const VideoStreamsResult({
    this.audioStreams = const [],
    this.videoStreams = const [],
    this.mixedStreams = const [],
    this.info,
    this.playability = const VideoPlayabilty(),
    this.loudnessDBData,
    this.hlsManifestUrl,
    this.dashManifestUrl,
    this.expired = true,
    this.videoId,
    this.captions = const [],
    this.overlay,
    this.endscreens = const [],
  });

  Map<String, AudioStream> get audioStreamsOrganizedByLanguage => const {};

  // 判断占位流结果是否需要重新获取。
  bool hasExpired() => expired;
}

