/// 端屏卡片的相对布局信息。
class EndscreenDisplay {
  final double top;
  final double left;
  final double width;
  final double aspectRatio;

  const EndscreenDisplay({this.top = 0, this.left = 0, this.width = 1, this.aspectRatio = 16 / 9});
}

class EndScreenItemVideo extends EndscreenItemBase {
  final String? videoId;
  final String? title;
  final int? viewsCount;
  final String? viewsCountText;
  final String? channelId;

  const EndScreenItemVideo({
    this.videoId,
    this.title,
    this.viewsCount,
    this.viewsCountText,
    this.channelId,
    super.display,
    super.thumbnails,
  }) : super(type: VideoEndScreenItemType.video);
}

class EndScreenItemChannel extends EndscreenItemBase {
  final String? channelId;
  final String? title;

  const EndScreenItemChannel({this.channelId, this.title, super.display, super.thumbnails}) : super(type: VideoEndScreenItemType.channel);
}

class EndScreenItemPlaylist extends EndscreenItemBase {
  final PlaylistBasicInfo basicInfo;

  const EndScreenItemPlaylist({this.basicInfo = const PlaylistBasicInfo(), super.display, super.thumbnails}) : super(type: VideoEndScreenItemType.playlist);
}

